/*
 * Client-side logic for the auto-discovering blog index on index.html.
 * Loaded as a plain script (no module system), same convention as
 * assets/markdown.js. Reads /index.json (generated by
 * scripts/build-index.mjs) and renders:
 *   - an infinite-scroll post list (IntersectionObserver, no pagination)
 *   - a left sidebar listing every post title (newest first)
 *   - tag filters (right column on desktop, top on mobile via CSS)
 * Everything is derived dynamically from index.json — nothing hardcoded.
 */

const BLOG_PAGE_SIZE = 6;

let allPosts = [];       // cached index.json content, newest first
let activeTag = "";      // current tag filter
let activeQuery = "";    // current search query
let renderedCount = 0;   // how many posts already rendered in the list
let observer = null;

function parseQueryParams(search) {
  const p = new URLSearchParams(search);
  return { tag: p.get("tag") || "", q: p.get("q") || "" };
}

function buildQueryString({ tag, q }) {
  const p = new URLSearchParams();
  if (tag) p.set("tag", tag);
  if (q) p.set("q", q);
  const s = p.toString();
  return s ? `?${s}` : "";
}

function filterPosts(posts, tag, q) {
  let result = posts;
  if (tag) result = result.filter((post) => post.tags.includes(tag));
  const needle = (q || "").trim().toLowerCase();
  if (needle) {
    result = result.filter((post) => {
      const haystack = [post.title, post.description, ...post.tags]
        .join(" ")
        .toLowerCase();
      return haystack.includes(needle);
    });
  }
  return result;
}

async function fetchBlogIndex() {
  if (allPosts.length) return allPosts;
  const res = await fetch("/index.json");
  if (!res.ok) throw new Error(`index.json fetch failed: ${res.status}`);
  allPosts = await res.json();
  return allPosts;
}

// Guarantee newest-first ordering for the sidebar regardless of source order.
function sortedNewestFirst(posts) {
  return [...posts].sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? 1 : -1;
    return a.slug < b.slug ? 1 : a.slug > b.slug ? -1 : 0;
  });
}

function postCardHTML(post) {
  return `
<a class="post-card" href="/blog/post.html?slug=${post.slug}">
<h3>${post.title}</h3>
<p class="desc">${post.description}</p>
<div class="meta">
${post.tags.map((t) => `<span class="badge">${t}</span>`).join("")}
<span class="date">${post.date}</span>
<span class="cta">อ่านบทความ →</span>
</div>
</a>`;
}

function renderTagFilters() {
  const tags = [...new Set(allPosts.flatMap((p) => p.tags))].sort();
  document.getElementById("tag-filters").innerHTML = tags
    .map((t) => {
      const active = t === activeTag ? " active" : "";
      return `<button type="button" class="tag-chip${active}" data-tag="${t}">${t}</button>`;
    })
    .join("");
}

function renderSidebar() {
  const list = document.getElementById("all-posts-list");
  list.innerHTML = sortedNewestFirst(allPosts)
    .map(
      (post) =>
        `<li><a href="/blog/post.html?slug=${post.slug}">${post.title}</a></li>`
    )
    .join("");
}

function getFilteredPosts() {
  return filterPosts(allPosts, activeTag, activeQuery);
}

function updateSentinel(hasMore) {
  const sentinel = document.getElementById("scroll-sentinel");
  if (!sentinel) return;
  sentinel.style.display = hasMore ? "block" : "none";
}

function appendNextPage(filtered) {
  const list = document.getElementById("blog-list");
  const next = filtered.slice(renderedCount, renderedCount + BLOG_PAGE_SIZE);
  if (next.length === 0) return;
  renderedCount += next.length;
  list.insertAdjacentHTML("beforeend", next.map(postCardHTML).join(""));
  const hasMore = renderedCount < filtered.length;
  updateSentinel(hasMore);
  // If the sentinel is still within view after appending (short content or a
  // very tall viewport), keep loading until it's pushed below the fold so the
  // IntersectionObserver doesn't stall waiting for a state change.
  if (hasMore) {
    const sentinel = document.getElementById("scroll-sentinel");
    const rect = sentinel.getBoundingClientRect();
    if (rect.top < window.innerHeight + 200) {
      requestAnimationFrame(() => appendNextPage(filtered));
    }
  }
}

function renderList(filtered) {
  const list = document.getElementById("blog-list");
  list.innerHTML = "";
  renderedCount = 0;
  if (filtered.length === 0) {
    list.innerHTML = "<p>ไม่พบบทความที่ตรงกับคำค้นหา</p>";
    updateSentinel(false);
    return;
  }
  appendNextPage(filtered);
}

async function renderBlogIndex() {
  const listEl = document.getElementById("blog-list");
  try {
    await fetchBlogIndex();
  } catch (e) {
    listEl.innerHTML =
      "<p>โหลดรายการบทความไม่สำเร็จ — อ่านบทความได้ที่ dev.to ด้านล่าง</p>";
    document.getElementById("tag-filters").innerHTML = "";
    document.getElementById("all-posts-list").innerHTML = "";
    updateSentinel(false);
    return;
  }

  const { tag, q } = parseQueryParams(location.search);
  activeTag = tag;
  activeQuery = q;
  const searchInput = document.getElementById("blog-search");
  if (searchInput && searchInput.value !== q) searchInput.value = q;

  renderTagFilters();
  renderSidebar();
  renderList(getFilteredPosts());
}

// Update URL + in-memory filter state without a full re-render.
function navigate({ tag, q }) {
  activeTag = tag;
  activeQuery = q;
  const qs = buildQueryString({ tag, q });
  history.pushState({}, "", qs || location.pathname);
}

function initBlogIndexEvents() {
  document.getElementById("tag-filters").addEventListener("click", (e) => {
    const btn = e.target.closest(".tag-chip");
    if (!btn) return;
    const nextTag = activeTag === btn.dataset.tag ? "" : btn.dataset.tag;
    navigate({ tag: nextTag, q: activeQuery });
    renderTagFilters();
    renderList(getFilteredPosts());
  });

  let debounceTimer;
  document.getElementById("blog-search").addEventListener("input", (e) => {
    clearTimeout(debounceTimer);
    const value = e.target.value;
    debounceTimer = setTimeout(() => {
      navigate({ tag: activeTag, q: value });
      renderList(getFilteredPosts());
    }, 200);
  });

  window.addEventListener("popstate", () => {
    const { tag, q } = parseQueryParams(location.search);
    activeTag = tag;
    activeQuery = q;
    const searchInput = document.getElementById("blog-search");
    if (searchInput && searchInput.value !== q) searchInput.value = q;
    renderTagFilters();
    renderList(getFilteredPosts());
  });

  observer = new IntersectionObserver(
    (entries) => {
      if (entries.some((entry) => entry.isIntersecting)) {
        appendNextPage(getFilteredPosts());
      }
    },
    { rootMargin: "200px 0px" }
  );
  const sentinel = document.getElementById("scroll-sentinel");
  if (sentinel) observer.observe(sentinel);
}
